import { RESOURCES, BUILDINGS, INFRA, RESEARCH, STOCKS, BANKS, BONDS, VENTURES, TIERS, ACHIEVEMENTS, POLICIES, DAY, HOUR, PROPERTIES, RELEASE } from './data.mjs';
import { price, quote, assets, capacity, warehouseCapacity, buildingRate, buildQuote, upgradeQuote, bankRate, creditLimit, debtRate, researchCost, prestigeReward, referencePrice, optionQuote, supplyPlan } from './engine.mjs';
import { icon, mark } from './icons.mjs';
import {optionPrice} from './math.mjs';

export const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
export function number(n, decimals = 0) { return Number(n || 0).toLocaleString('de-DE', { maximumFractionDigits: decimals, minimumFractionDigits: decimals }); }
export function compact(n) {
  if(!Number.isFinite(n))return n===Infinity?'∞':n===-Infinity?'−∞':'—';
  if(Math.abs(n)>=1e15){const [coefficient,exponent]=n.toExponential(2).split('e');return `${number(Number(coefficient),2)} × 10^${Number(exponent)}`;}
  return Math.abs(n)>=1e12?`${number(n/1e12,2)} Bio.`:Math.abs(n) >= 1e9 ? `${number(n / 1e9, 2)} Mrd.` : Math.abs(n) >= 1e6 ? `${number(n / 1e6, 2)} Mio.` : Math.abs(n) >= 1e5 ? `${number(n / 1000, 1)} Tsd.` : number(n);
}
export const money = (n, decimals = 0) => `${number(n, decimals)} €`;
export const cash = n => `${compact(n)} €`;
export const signed = (n, suffix = ' €') => `${n >= 0 ? '+' : '−'}${compact(Math.abs(n))}${suffix}`;
export const pct = (n, decimals = 1) => `${number(n * 100, decimals)} %`;
export function duration(seconds) {
  const s = Math.max(0, Math.round(seconds));
  return s >= 86400 ? `${Math.floor(s / 86400)} T ${Math.floor(s % 86400 / 3600)} Std.` : s >= 3600 ? `${Math.floor(s / 3600)} Std. ${Math.floor(s % 3600 / 60)} Min.` : s >= 60 ? `${Math.floor(s / 60)} Min.` : `${s} Sek.`;
}
export const gameTime = s => `Tag ${Math.floor(s.elapsed / DAY) + 1} · ${String(Math.floor(s.elapsed % DAY / HOUR)).padStart(2, '0')}:00`;
export const updateBanner = ui => ui.updateReady ? `<aside class="update-banner" aria-label="App-Update"><div>${icon('refresh')}<span><strong>Eine neue Version ist bereit.</strong><small>Dein Spielstand wird beim Wechsel gesichert.</small></span></div><button class="primary small" data-action="update">Update laden</button></aside>` : '';
const disabled = condition => condition ? ' disabled' : '';
const act = (action, id = '') => `data-action="${action}"${id !== '' ? ` data-id="${esc(id)}"` : ''}`;
const infoNames={building:BUILDINGS,infra:INFRA,resource:RESOURCES,research:RESEARCH,stock:STOCKS,bank:BANKS,bond:BONDS,venture:VENTURES,property:PROPERTIES,policy:POLICIES};
export const info = (key,label='') => `<button class="info-button" ${act('info',key)} aria-label="${esc(label||'Info: '+(infoNames[key.split(':')[0]]?.[key.split(':')[1]]?.name||'Funktionsweise'))}">${icon('info')}</button>`;
const empty = (name, text, glyph = 'box') => `<div class="empty">${icon(glyph)}<h3>${name}</h3><p>${text}</p></div>`;
const pageHelp={'Wertschöpfung':'planner','Angebot & Nachfrage':'resource:wood','Zeit ist Kapital':'credit','Wissen verändert alles':'research:forestry','Vertrauen wird belohnt':'contracts','Deine Geschichte':'offline'};
const head = (eyebrow, title, subtitle = '', extra = '') => `<div class="between page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title} ${info(pageHelp[eyebrow]||'overview','Diesen Bereich erklären')}</h1>${subtitle ? `<p>${subtitle}</p>` : ''}</div>${extra}</div>`;
const quantity = ui => `<div class="quantity-label">Schrittweite ${info('quantity')}<div class="segmented" aria-label="Schrittweite">${[1,10,100].map(n => `<button ${act('qty', n)} class="${ui.qty === n ? 'active' : ''}" aria-pressed="${ui.qty === n}">${n}</button>`).join('')}</div></div>`;
const resource = (id, n) => `<span class="resource">${icon(RESOURCES[id].icon)}${number(n, n % 1 ? 1 : 0)} ${RESOURCES[id].name}</span>`;
const meter = (name, used, total, suffix = '', warning = false) => `<div class="meter ${warning ? 'warning' : ''}"><div class="meter-label"><span>${name}</span><span class="number">${number(used, used % 1 ? 1 : 0)} / ${number(total)}${suffix}</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100, used / Math.max(1,total) * 100)}%"></div></div></div>`;

export function chart(values, large = false, label = '') {
  const data = values.length > 1 ? values : [values[0] || 0, values[0] || 0];
  const min = Math.min(...data), max = Math.max(...data), span = max - min || Math.max(1, max * 0.05), w = large ? 600 : 100, h = large ? 150 : 32, padding = large ? 10 : 3;
  const points = data.map((v, i) => `${(i / (data.length - 1) * w).toFixed(1)},${(h - padding - ((v - min) / span) * (h - padding * 2)).toFixed(1)}`).join(' ');
  return `<svg class="${large ? 'chart' : 'spark'}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="${esc(label || 'Kursverlauf')}">${large ? `<line x1="0" x2="${w}" y1="${h/2}" y2="${h/2}"/><line x1="0" x2="${w}" y1="${h}" y2="${h}"/>` : ''}<polyline points="${points}"/></svg>`;
}

export function menu(s, ui) {
  return `<main class="menu-screen" id="content"><div class="menu-top">${mark()}<span class="status-pill"><i class="status-dot"></i>${ui.offlineReady ? 'Offline bereit' : 'Lokal. Privat. Zeitlos.'}</span></div>${updateBanner(ui)}<div class="menu-main"><div class="menu-hero"><div class="eyebrow">Eine Ökonomie · Ein Anfang</div><h1 class="menu-logo">NULL</h1><p class="menu-tagline">Aus wenig wird alles.</p><p class="menu-description">Ein paar Rohstoffe. Eine Entscheidung.<br>Ein System, das weiterdenkt.<br>Deine Wirtschaft wächst — auch ohne dich.</p></div><div class="menu-actions">${s ? `<button class="primary" ${act('continue')}><span>Unternehmen fortsetzen</span>${icon('arrow')}</button>` : ''}<button ${act('new')} class="${s ? '' : 'primary'}"><span>Neues Unternehmen</span>${icon('plus')}</button><button ${act('saves')}><span>Spielstände</span>${icon('save')}</button><button ${act('guide')}><span>Spielanleitung</span>${icon('book')}</button><button ${act('install')} class="ghost"><span>Auf dem iPhone installieren</span>${icon('download')}</button>${s ? `<div class="menu-save">${esc(s.name)} · ${TIERS[s.tier].name}<br>${gameTime(s)} · ${cash(s.cash)} verfügbar</div>` : ''}</div></div><footer class="menu-footer"><span>PRODUKTION · HANDEL · KAPITAL</span><span>Kein Konto. Kein Tracking. Dein Spiel.</span></footer></main>`;
}

export function frame(s, ui, content) {
  const tabs = [['overview','dashboard','Übersicht'],['production','factory','Betriebe'],['market','market','Markt'], ...(s.tier >= 1 ? [['finance','bank','Finanzen'],['research','flask','Forschung']] : []),['contracts','file','Aufträge'],['journal','clock','Chronik']];
  const mobile = tabs.filter(([id]) => ['overview','production','market','finance'].includes(id)); mobile.push(['more','more','Mehr']);
  const isMore = !mobile.some(([id]) => id === ui.tab);
  return `<div class="shell"><header class="topbar"><div class="row"><button class="brand" ${act('menu')} aria-label="Hauptmenü">${mark()}NULL</button><span class="company">${esc(s.name)}</span></div><div class="top-actions"><span class="status-pill"><i class="status-dot"></i>${ui.offlineReady ? 'Offline bereit' : 'Offline-Cache lädt'}</span><span class="clock mono">${gameTime(s)}</span><button class="icon-button ghost" ${act('saves')} aria-label="Spielstände">${icon('save')}</button></div></header>${updateBanner(ui)}<nav class="desktop-nav" aria-label="Spielbereiche">${tabs.map(([id,glyph,name]) => `<button ${act('tab',id)} class="${ui.tab === id ? 'active' : ''}">${icon(glyph)}${name}</button>`).join('')}<button ${act('tab','more')} class="${ui.tab === 'more' ? 'active' : ''}">${icon('more')}Mehr</button></nav><main id="content" tabindex="-1">${content}</main><footer class="footer-note"><span>${ui.lastSaved ? `Automatisch gespeichert · ${new Date(ui.lastSaved).toLocaleTimeString('de-DE', {hour:'2-digit',minute:'2-digit'})}` : 'Automatische Sicherung alle 15 Sekunden'}${ui.saveError ? ' · Speicherung eingeschränkt' : ''}</span><span>${RELEASE} · 1 Spieltag = 24 echte Min.</span></footer><nav class="bottom-nav" aria-label="Spielbereiche" style="grid-template-columns:repeat(${mobile.length},1fr)">${mobile.map(([id,glyph,name]) => `<button ${act('tab',id)} class="${ui.tab === id || (id === 'more' && isMore) ? 'active' : ''}">${icon(glyph)}<span>${name}</span></button>`).join('')}</nav></div>`;
}

function tutorial(s) {
  if (!s.tutorial) return '';
  const steps = [
    { done:s.stats.built > 0, text:'Baue deinen ersten Holzfäller.', tab:'production' },
    { done:Object.values(s.automation).some(a => a.mode === 'sell' || a.mode === 'both'), text:'Verkaufe Überschüsse automatisch am Markt.', tab:'market' },
    { done:s.stats.contracts > 0, text:'Erfülle einen Lieferauftrag für eine Prämie.', tab:'contracts' },
    { done:s.tier >= 1, text:'Erreiche 2.000 € Vermögen. Entdecke mehr.', tab:'production' },
  ];
  return `<section class="panel flat"><div class="between"><div><div class="eyebrow">Deine ersten Schritte</div><h3 class="mt8">Jedes Imperium beginnt klein.</h3></div><button class="icon-button ghost" ${act('dismissTutorial')} aria-label="Einführung ausblenden">${icon('close')}</button></div><div class="tutorial-steps">${steps.map((t,i) => `<div class="tutorial-step ${t.done ? 'done' : ''}"><span class="step-number">${t.done ? icon('check') : i+1}</span><span>${t.text}</span>${!t.done ? `<button ${act('tab',t.tab)}>${icon('arrow')}</button>` : ''}</div>`).join('')}</div></section>`;
}

export function overview(s, ui) {
  const a = assets(s), c = capacity(s), next = TIERS[s.tier + 1], active = Object.values(s.buildings).reduce((n,b) => n + b.active, 0);
  let warnings = [];
  if (s.cash < Math.max(100, c.wages)) warnings.push('<strong>Liquidität knapp.</strong> Waren im Lager bezahlen keine Löhne. Verkaufe Überschüsse oder nutze automatische Verkäufe.');
  if (c.staffing < 0.99) warnings.push('<strong>Personal fehlt.</strong> Wohnquartiere schaffen zusätzliche Arbeitskräfte.');
  if (c.power < 0.99) warnings.push('<strong>Energie fehlt.</strong> Prüfe Kraftwerke und ihren Kohlevorrat.');
  if (c.logistics < 0.99) warnings.push('<strong>Transport ausgelastet.</strong> Ein Logistikzentrum erhöht die Kapazität.');
  if (Object.values(s.inventory).some(n => n >= warehouseCapacity(s) * 0.98)) warnings.push('<strong>Lager fast voll.</strong> Verkaufe Waren oder baue Lagerhallen.');
  return `<div class="hero-balance"><div><div class="eyebrow">Verfügbares Kapital ${info('overview')}</div><div class="stat-value number">${cash(s.cash)}</div><div class="stat-sub">${esc(s.name)} · ${TIERS[s.tier].name}</div></div><div class="align-right"><div class="eyebrow">Nettovermögen</div><div class="secondary-value number">${cash(a.total)}</div><div class="stat-sub">inkl. Waren & Buchwerten</div></div></div>${warnings.length ? `<div class="notice">${warnings.join('<br><br>')}<div class="row wrap mt16">${c.staffing<.99||c.power<.99||c.logistics<.99?`<button class="small" ${act('goLab')}>Kapazitäten ausbauen</button>`:''}<button class="small" ${act('tab','market')}>Zum Markt ${icon('arrow')}</button>${s.cash < 100 ? `<button class="small" ${act('liquidate')}>Lager zu Geld machen</button><button class="small" ${act('emergency')}>Notauftrag</button>${info('aid')}${a.total<0?`<button class="small" ${act('restructure')}>Unternehmen sanieren</button>`:''}` : ''}</div></div>` : ''}<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Die Entwicklung deines Unternehmens</h3>${icon('chart')}</div>${chart(s.stats.history.map(h => h.wealth), true, 'Nettovermögen im Verlauf der letzten 96 Spielstunden')}<div class="chart-caption"><span>${s.stats.history.length > 1 ? 'Letzte ' + s.stats.history.length + ' Spielstunden' : 'Deine Geschichte beginnt jetzt'}</span><span>${cash(a.total)}</span></div><div class="metric-grid"><div><small>Cashflow / h</small><strong class="number ${s.stats.lastProfit < 0 ? 'negative' : ''}">${signed(s.stats.lastProfit)}</strong></div><div><small>Produziert</small><strong class="number">${compact(s.stats.produced)}</strong></div><div><small>Aktive Betriebe</small><strong class="number">${number(active)}</strong></div></div><p class="fine-print">Cashflow = Warenumsatz − Einkauf − laufende Kosten der letzten Spielstunde. Ungesicherte Lagerwerte sind kein Umsatz.</p></section><section class="panel"><div class="panel-header"><h3>Dein System</h3>${icon('gear')}</div>${meter('Arbeitskräfte',c.staff,c.workers,'',c.staffing < 1)}${meter('Energie',c.energy,c.availableEnergy,'',c.power < 1)}${meter('Transport',c.freight,c.transport,'',c.logistics < 1)}<div class="between mt24"><span class="muted" style="font-size:11px">Lagerplatz je Ware</span><span class="number">${number(warehouseCapacity(s))}</span></div>${s.tier >= 2 ? `<div class="between mt8"><span class="muted" style="font-size:11px">Umweltbelastung</span><span class="number">${number(c.pollution,1)}</span></div>` : ''}${next ? `<div class="next-era"><div class="divider"></div><div class="between"><span class="eyebrow">Ein neuer Horizont</span><span class="number">${pct(Math.min(1,s.stats.peak/next.wealth),0)}</span></div>${meter('Nächste Entdeckung',s.stats.peak,next.wealth,' €')}<p class="fine-print">Was dahinter liegt, entdeckst du erst, wenn du dort bist.</p></div>` : `<p class="fine-print">Alle Wirtschaftsepochen entdeckt. Wie groß kann dein Unternehmen werden?</p>`}</section>${tutorial(s)}<section class="panel"><div class="panel-header"><h3>${s.event ? s.event.name : 'Die Welt um dich herum'}</h3>${icon(s.event?.icon || 'globe')}</div>${s.event ? `<p style="font-size:12px">${esc(s.event.description)}</p><p class="fine-print">Noch ${duration(s.event.end-s.elapsed)} echte Zeit</p>` : `<div class="list-item between"><span class="muted">Konjunktur</span><span>${s.economy.phase}</span></div><div class="list-item between"><span class="muted">Nachfrageindex</span><span class="number">${number(s.economy.cycle*100,1)}</span></div><p class="fine-print">Die Konjunktur bewegt sich in Zyklen. Ereignisse verschieben Angebot, Nachfrage und Kapazitäten.</p>`}<div class="divider"></div><div class="between"><span class="muted" style="font-size:12px">Reputation</span><span class="number">${number(s.reputation)} / 100</span></div><p class="fine-print">Zuverlässige Lieferungen verbessern Gebühren und Kreditbedingungen.</p></section></div>${s.journal.length ? `<div class="subheading"><span>Zuletzt passiert</span><button class="small ghost" ${act('tab','journal')}>Chronik ${icon('arrow')}</button></div><div class="panel flat">${s.journal.slice(0,3).map(j => `<div class="list-item"><p style="color:var(--text);font-size:12px">${esc(j.text)}</p><p>Tag ${Math.floor(j.at/DAY)+1} · ${number(Math.floor(j.at%DAY/HOUR))}:00</p></div>`).join('')}</div>` : ''}`;
}

function buildingCard(s, ui, id) {
  const b = BUILDINGS[id], own = s.buildings[id], q = buildQuote(s,id,ui.qty), rate = buildingRate(s,id), expanded = ui.open.has(`b-${id}`);
  const state = !own.count ? 'Noch nicht gebaut' : !own.active ? 'Pausiert' : rate.guarded ? 'Marge zu niedrig' : !rate.storage ? 'Lager voll' : rate.cash <= 0 ? 'Kein Betriebskapital' : rate.cash < .99 ? 'Liquidität begrenzt' : rate.global < .99 ? 'Kapazität begrenzt' : rate.supply < .99 ? 'Vorprodukt fehlt' : 'In Produktion';
  return `<article class="building-card"><div class="building-main"><div class="between"><div class="row"><div class="building-icon">${icon(b.icon)}</div><div><h3>${b.name} ${info('building:'+id)}</h3><div class="meta">${TIERS[b.tier].name}${own.level ? ` · Ausbau ${own.level}` : ''}</div></div></div><span class="building-count number">${own.count}</span></div><div class="recipe">${Object.entries(b.input).map(([r,n]) => resource(r,n * rate.mult)).join(' + ') || '<span>Rohstoffgewinnung</span>'}${icon('arrow')}${Object.entries(b.output).map(([r,n]) => resource(r,n * rate.mult)).join(' + ')}<small>/ h je Betrieb</small></div><div class="build-controls"><button ${act('demolish',id)} aria-label="${ui.qty} ${b.name} abbauen"${disabled(own.count < ui.qty)}>−${ui.qty}</button><div class="price number">${cash(q.total)}<small>${q.materialCash > 0 ? 'inkl. fehlender Baustoffe' : `für ${ui.qty} ${ui.qty === 1 ? 'Betrieb' : 'Betriebe'}`}</small></div><button class="primary" ${act('build',id)}${disabled(s.cash + 1e-7 < q.total || own.count + ui.qty > 10000)}>+${ui.qty} bauen</button></div></div><div class="card-footer"><span class="status-tag ${state !== 'In Produktion' ? 'idle' : ''}">${state}</span><div class="row gap8"><button ${act('preview',id)}>Bau prüfen</button><button ${act('expand',`b-${id}`)} aria-expanded="${expanded}">Verwalten ${icon(expanded ? 'minus' : 'plus')}</button></div></div>${expanded ? `<div class="card-detail"><div class="detail-grid"><p>Personal / Betrieb<strong>${number(b.staff * Math.pow(.92,s.research.automation),1)}</strong></p><p>Lohn / Betrieb / h<strong>${money(b.wage * (1+own.level*.08) * POLICIES[s.policy].wage)}</strong></p><p>Energie · Transport<strong>${b.energy} · ${b.freight}</strong></p><p>Indikative Marge / h<strong>${signed(rate.margin)}</strong></p><p>Aktive Betriebe<strong>${own.active} / ${own.count}</strong></p><p>Auslastung jetzt<strong>${pct(rate.utilization,0)}</strong></p></div><p class="fine-print">Die Marge bewertet Ein- und Ausgänge zum aktuellen Mittelkurs; Gebühren, Umweltabgaben und Engpässe sind darin nicht enthalten. Vorprodukte müssen im Lager liegen.</p>${own.count ? `<div class="row wrap mt16"><button class="small" ${act('active',id)} data-delta="-${ui.qty}"${disabled(!own.active)}>−${ui.qty} aktiv</button><button class="small" ${act('active',id)} data-delta="${ui.qty}"${disabled(own.active === own.count)}>+${ui.qty} aktiv</button><button class="small" ${act('pause',id)}>${icon(own.active ? 'pause' : 'play')} ${own.active ? 'Alle pausieren' : 'Alle starten'}</button></div><button class="wfull mt8" ${act('upgrade',id)}${disabled(own.level >= 5 || s.cash < upgradeQuote(s,id))}>${own.level >= 5 ? 'Voll ausgebaut' : `Ausbau ${own.level+1} · ${cash(upgradeQuote(s,id))}`}</button>${Object.keys(b.input).length?`<button class="wfull mt8" ${act('setupSupplies',id)}>Vorprodukt-Einkauf einrichten</button>`:''}<p class="fine-print">Jede Ausbaustufe gilt für alle Betriebe dieses Typs, auch künftige: +18 % Grundproduktion und +8 % Grundlohn.</p>` : ''}</div>` : ''}</article>`;
}

function infrastructure(s,ui) {
  return `<div class="building-grid">${Object.entries(INFRA).filter(([,d]) => d.tier <= s.tier).map(([id,d]) => { const q=buildQuote(s,id,ui.qty,true); return `<article class="building-card"><div class="building-main"><div class="between"><div class="row"><div class="building-icon">${icon(d.icon)}</div><div><h3>${d.name} ${info('infra:'+id)}</h3><p class="meta">${TIERS[d.tier].name}</p></div></div><span class="number building-count">${s.infra[id]}</span></div><div class="build-controls mt24"><button ${act('demolishInfra',id)} aria-label="${ui.qty} ${d.name} abbauen"${disabled(s.infra[id] < ui.qty)}>−${ui.qty}</button><div class="price number">${cash(q.total)}<small>für ${ui.qty} Einheiten</small></div><button class="primary" ${act('buildInfra',id)}${disabled(q.total > s.cash)}>+${ui.qty} bauen</button></div></div></article>`; }).join('')}</div>`;
}

function strategy(s) {
  return `${s.tier>=2?`<section class="panel mt16" style="margin-bottom:20px"><div class="between"><h3>Margenwächter ${info('profitGuard')}</h3><button class="small ${s.profitGuard?'primary':''}" ${act('profitGuard')}>${s.profitGuard?'Aktiv':'Inaktiv'}</button></div></section>`:''}<div class="grid2">${Object.entries(POLICIES).filter(([id])=> id !== 'green' || s.tier >= 2).map(([id,p]) => `<section class="panel"><div class="between"><h3>${p.name} ${info('policy:'+id)}</h3>${s.policy===id ? icon('check') : ''}</div><p class="details-copy">${p.description}</p><button class="wfull mt24 ${s.policy===id?'primary':''}" ${act('policy',id)}${disabled(s.policy===id)}>${s.policy===id?'Aktive Strategie':'Strategie wählen'}</button></section>`).join('')}</div><section class="panel mt24"><h3>Reihenfolge der Produktion</h3><p class="mt8" style="font-size:12px">Bei knappen Vorprodukten entscheidet die Reihenfolge, welcher Betrieb zuerst bedient wird.</p><div class="segmented mt16"><button ${act('priority','balanced')} class="${s.priority==='balanced'?'active':''}">Von Rohstoff zu Produkt</button><button ${act('priority','advanced')} class="${s.priority==='advanced'?'active':''}">Höchste Veredelung zuerst</button></div></section>`;
}

export function production(s,ui) {
  const sub = ui.productionTab;
  const ids = Object.keys(BUILDINGS).filter(id => BUILDINGS[id].tier <= s.tier && (ui.buildFilter !== 'owned' || s.buildings[id].count > 0) && (ui.buildFilter !== 'raw' || !Object.keys(BUILDINGS[id].input).length));
  return `${head('Wertschöpfung','Etwas erschaffen.','Baue Kapazitäten. Verbinde Rohstoffe mit Ideen.')}<div class="toolbar"><div class="segmented">${[['business','Produktion'],['infra','Infrastruktur'],...(s.tier>=1?[['planner','Planung'],['strategy','Strategie']]:[])].map(([id,name])=>`<button ${act('productionTab',id)} class="${sub===id?'active':''}">${name}</button>`).join('')}</div>${['business','infra'].includes(sub)?quantity(ui):''}</div>${sub==='business'?`<div class="toolbar"><span class="muted" style="font-size:11px">${number(Object.values(s.buildings).reduce((n,b)=>n+b.count,0))} Betriebe · ${cash(s.cash)} verfügbar</span><select data-setting="buildFilter" aria-label="Betriebe filtern"><option value="all" ${ui.buildFilter==='all'?'selected':''}>Alle bekannten Betriebe</option><option value="owned" ${ui.buildFilter==='owned'?'selected':''}>Meine Betriebe</option><option value="raw" ${ui.buildFilter==='raw'?'selected':''}>Rohstoffgewinnung</option></select></div><div class="building-grid">${ids.map(id=>buildingCard(s,ui,id)).join('')}</div>${!ids.length?empty('Noch ist es still.','Baue deinen ersten Betrieb in der Ansicht „Alle bekannten Betriebe“.','factory'):''}`:sub==='infra'?infrastructure(s,ui):sub==='planner'?plannerView(s):strategy(s)}${s.tier<6 && ['business','infra'].includes(sub)?`<div class="locked-card mt24">${icon('compass')}<div><h3>Die Welt ist größer, als sie scheint.</h3><p>Wachse weiter. Neue Möglichkeiten erscheinen, wenn du bereit bist.</p></div></div>`:''}`;
}

export function buildingPreview(plan){
  const b=BUILDINGS[plan.id],metricNames={staff:'Arbeitskräfte',energy:'Energie',freight:'Transport'};
  const cost=value=>value===null?'Nicht finanzierbar':cash(value);
  const warnings=[];
  if(!plan.withinLimit)warnings.push('Das Limit von 10.000 Betrieben dieses Typs würde überschritten.');
  else if(!plan.affordable)warnings.push(plan.missingCash===null?'Dieser Bau ist nicht finanzierbar.':`Es fehlen ${cash(plan.missingCash)} für den Bau.`);
  if(plan.affectsExisting){
    const before=pct(plan.utilizationBefore,1),after=pct(plan.utilizationAfter,1);
    warnings.push(before===after?`Die technische Auslastung sinkt geringfügig (auf rund ${after}). Das betrifft auch bestehende Betriebe.`:`Die technische Auslastung sinkt von ${before} auf ${after}. Das betrifft auch bestehende Betriebe.`);
  }
  if(plan.lowReserve)warnings.push('Nach dem Bau bleibt weniger als eine Reserve für zwei Spielstunden der zusätzlichen laufenden Kosten.');
  if(plan.guarded)warnings.push('Der Margenwächter würde diesen Betrieb bei den aktuellen Kursen anhalten.');
  return `<div class="cash-control mt24"><div class="between wfull"><span class="muted">Zusätzliche Betriebe</span><output class="number" style="font-size:28px">${plan.quantity}</output></div><div class="cash-buttons wfull">${[-100,-10,-1,1,10,100].map(delta=>`<button ${act('previewQuantity',plan.id)} data-delta="${delta}"${disabled(delta<0?plan.quantity===1:plan.quantity===100)}>${delta>0?'+':'−'}${Math.abs(delta)}</button>`).join('')}</div></div>${warnings.length?`<div class="notice">${warnings.map(esc).join('<br><br>')}</div>`:''}<div class="detail-grid"><p>Gesamter Baupreis<strong class="number">${cost(plan.cost)}</strong></p><p>Nach Bau, ohne Prämien<strong class="number">${cash(plan.cashAfter)}</strong></p><p>Löhne / h bei Volllast<strong class="number">${cash(plan.wages)}</strong></p><p>Deckungsbeitrag / h vor Steuer<strong class="number">${signed(plan.capacityMargin)}</strong></p></div><div class="preview-recipe"><span class="eyebrow">Zusätzliche Sollmengen / h</span><div class="recipe mt8">${plan.inputs.map(r=>resource(r.id,r.quantity)).join(' + ')||'<span>Rohstoffgewinnung</span>'}${icon('arrow')}${plan.outputs.map(r=>resource(r.id,r.quantity)).join(' + ')}</div></div><details class="preview-section"${plan.deficits.length?' open':''}><summary>Gesamtkapazitäten · ${plan.deficits.length?`${plan.deficits.length} ${plan.deficits.length===1?'Engpass':'Engpässe'}`:'ausreichend'}</summary><p>Gesamtes Unternehmen nach dem Bau; bereits bestehende Engpässe sind enthalten.</p><div class="detail-grid mt16">${Object.entries(plan.capacity).map(([key,c])=>`<p>${metricNames[key]} nach dem Bau<strong class="number">${number(c.used,1)} / ${number(c.available,1)}</strong></p>`).join('')}<p>Technische Auslastung<strong class="number">${pct(plan.utilizationAfter,0)}</strong></p></div>${plan.deficits.map(d=>`<div class="preview-supply"><strong>${metricNames[d.metric]}: ${number(d.shortage,1)} fehlen</strong><p>${d.additionalShortage>1e-9?`${number(d.additionalShortage,1)} zusätzlich durch diesen Bau`:'Bereits bestehender Engpass'}</p><p>${d.options.length?d.options.map(o=>`${o.quantity}× ${INFRA[o.id].name} · ${o.withinLimit?cost(o.cost):'Baulimit überschritten'}`).join('<br>oder '):'Eine passende Erweiterung wurde noch nicht entdeckt.'}</p></div>`).join('')}${plan.capacity.energy.availableNow<plan.capacity.energy.available-1e-7?`<p class="mt8 muted">Mit dem aktuellen Kohlevorrat stehen momentan ${number(plan.capacity.energy.availableNow,1)} Energie zur Verfügung. Der technische Wert setzt Brennstoffversorgung voraus.</p>`:''}</details>${plan.supplies.length?`<details class="preview-section"${plan.supplies.some(r=>r.gap>0)?' open':''}><summary>Zulieferung · ${plan.supplies.filter(r=>r.gap>0).length} ungedeckte Ware${plan.supplies.filter(r=>r.gap>0).length===1?'':'n'}</summary>${plan.supplies.map(r=>`<div class="preview-supply"><div class="between"><strong>${RESOURCES[r.id].name}</strong><span class="number">${number(r.needed,1)} / h zusätzlich</span></div><p>${number(r.stock,1)} im Lager nach dem Bau · ${r.gap>0?`${number(r.gap,1)} / h fehlen dem gesamten Unternehmen`: 'Eigene Sollproduktion deckt den Gesamtbedarf.'}</p>${r.gap>0?`<p>${r.producer?`Alternative zum Markteinkauf: mindestens ${r.additionalProducers}× ${BUILDINGS[r.producer].name} zusätzlich bei Volllast.`:'Markteinkauf einplanen.'}</p>`:''}</div>`).join('')}</details>`:''}${plan.materials.length?`<details class="preview-section"><summary>Baustoffe · ${cost(plan.materialCost)} Einkauf enthalten</summary>${plan.materials.map(r=>`<div class="preview-supply"><strong>${RESOURCES[r.id].name} · ${number(r.needed)}</strong><p>${number(r.fromStock,1)} aus dem Lager · ${number(r.purchased,1)} werden beim Bau gekauft</p></div>`).join('')}</details>`:''}<details class="preview-section"><summary>${icon('info')} Rechenregeln & Annahmen</summary><p>Eine Spielstunde dauert eine echte Minute. Die Vorschau verwendet aktuelle Kurse, bekannte Rezepte und deine Live-Boni. Zusätzliche Offline-Boni sind nicht eingerechnet. Der Deckungsbeitrag bewertet alle Ausgänge als Marktverkauf und alle Vorprodukte als Markteinkauf, einschließlich Spanne und Gebühren. Löhne, zusätzlicher Brennstoff und zusätzliche Umweltabgaben sind abgezogen. Die technische Auslastung begrenzt den angezeigten Betrag.</p><p>Vorprodukte, freier Lagerplatz und Betriebskapital müssen vorhanden sein. Zulieferer werden mit Volllast gerechnet; deren eigene Vorprodukte und Kapazitäten sind zusätzlich zu planen. Die vorgeschlagenen Erweiterungen sind nicht Teil des angezeigten Baupreises. Bestehende Betriebe können durch neue Engpässe langsamer werden.</p><p>Steuern, Kreditzinsen, Mengen-Preiseffekte, Erfolgsprämien und zukünftige Marktänderungen sind nicht vorhergesagt. ${plan.paybackSeconds!==null?`Rechnerische Amortisation nur dieses Baupreises: ${duration(plan.paybackSeconds)} echte Zeit bei unverändertem Deckungsbeitrag. Das ist keine Gewinnzusage.`:'Bei dieser Versorgung und Bewertung ist keine rechnerische Amortisation gegeben.'} Der tatsächliche Bau wird beim Bestätigen neu zum dann gültigen Preis geprüft.</p></details>`;
}

function marketItem(s,ui,id) {
  const d=RESOURCES[id], p=price(s,id), m=s.market[id], a=s.automation[id], buy=quote(s,id,ui.qty,'buy'), sell=quote(s,id,ui.qty,'sell'), expanded=ui.open.has(`m-${id}`), change=(p/m.previous-1);
  const autoNames={off:'Manuell',sell:'Überschüsse verkaufen',buy:'Vorräte auffüllen',both:'Einkauf & Verkauf'};
  return `<article class="market-item"><div class="market-row"><div class="row market-name">${icon(d.icon)}<div><strong>${d.name} ${info('resource:'+id)}</strong><small>${TIERS[d.tier].name}</small></div></div><div class="market-price number">${money(p,2)}<small>${change>=0?'+':''}${pct(change,1)} / h</small></div>${chart([...m.history.slice(-47),p],false,`${d.name}: Preisverlauf`)}<div class="market-stock number">${number(s.inventory[id],1)}<small>von ${compact(warehouseCapacity(s))} im Lager</small></div><div class="market-actions"><button ${act('trade',id)} data-side="sell"${disabled(s.inventory[id]+1e-7<ui.qty)}>Verk. ${cash(sell.total)}</button><button ${act('trade',id)} data-side="buy"${disabled(s.cash+1e-7<buy.total || s.inventory[id]+ui.qty>warehouseCapacity(s))}>Kauf ${cash(buy.total)}</button></div></div><div class="market-auto"><span>${a.mode!=='off'?icon('refresh'):''} ${autoNames[a.mode]}</span><button ${act('expand',`m-${id}`)} aria-expanded="${expanded}">Automatik${s.tier>=1?' & Limit':''} ${icon(expanded?'minus':'plus')}</button></div>${expanded?`<div class="market-detail"><div class="auto-form"><div><label for="auto-${id}">Automatik</label><select id="auto-${id}" data-auto="${id}" data-field="mode">${Object.entries(autoNames).map(([v,n])=>`<option value="${v}"${a.mode===v?' selected':''}>${n}</option>`).join('')}</select></div><div><label for="low-${id}">Nachkaufen unter</label><div class="input-stepper"><button ${act('autoStep',id)} data-field="low" data-delta="-${ui.qty}" aria-label="Einkaufsschwelle senken">−</button><input id="low-${id}" type="number" inputmode="numeric" min="0" max="1000000000" value="${a.low}" data-auto="${id}" data-field="low"><button ${act('autoStep',id)} data-field="low" data-delta="${ui.qty}" aria-label="Einkaufsschwelle erhöhen">+</button></div></div><div><label for="high-${id}">Verkaufen über</label><div class="input-stepper"><button ${act('autoStep',id)} data-field="high" data-delta="-${ui.qty}" aria-label="Verkaufsschwelle senken">−</button><input id="high-${id}" type="number" inputmode="numeric" min="0" max="1000000000" value="${a.high}" data-auto="${id}" data-field="high"><button ${act('autoStep',id)} data-field="high" data-delta="${ui.qty}" aria-label="Verkaufsschwelle erhöhen">+</button></div></div></div><p class="fine-print">Die Automatik hält eine Lohnreserve zurück. Einkaufsschwelle ≤ Verkaufsschwelle. Für eigene Vorprodukte eine Reserve behalten, damit die Verarbeitung weiterläuft. Preise und Gebühren gelten auch automatisch.</p>${s.tier>=1?`<div class="divider"></div><button class="small" ${act('orderDialog',id)}>${icon('chart')} Limitauftrag anlegen</button>`:''}</div>`:''}</article>`;
}

export function market(s,ui) {
  const ids=Object.keys(RESOURCES).filter(id=>RESOURCES[id].tier<=s.tier && (ui.marketFilter!=='owned'||s.inventory[id]>.01) && (ui.marketFilter!=='auto'||s.automation[id].mode!=='off'));
  return `${head('Angebot & Nachfrage','Alles hat seinen Preis.','Preise reagieren auf Knappheit, Konjunktur und deine Handelsmengen.')}<div class="toolbar"><div class="segmented">${[['all','Alle Waren'],['owned','Mein Lager'],['auto','Automatik']].map(([id,n])=>`<button ${act('marketFilter',id)} class="${ui.marketFilter===id?'active':''}">${n}</button>`).join('')}</div>${quantity(ui)}</div><div class="market-head"><span>Ware</span><span>Mittelkurs</span><span>48 Stunden</span><span>Lager</span><span class="align-right">Handel für ${ui.qty}</span></div>${ids.map(id=>marketItem(s,ui,id)).join('')}${!ids.length?empty('Keine Waren in dieser Ansicht.','Wähle einen anderen Filter oder richte eine Automatik ein.','market'):''}<p class="fine-print">Kauf- und Verkaufsschaltflächen zeigen den Gesamtbetrag für ${ui.qty} Einheiten inklusive Gebühren und Preiseffekt. Der Mittelkurs ist ein Referenzpreis. Große Aufträge bewegen den Markt.</p>${s.orders.length?`<div class="subheading">Aktive Limitaufträge <span class="muted">${s.orders.length} / 20</span></div><div class="panel">${s.orders.map(o=>`<div class="list-item between"><div><h3 style="font-size:12px">${o.side==='buy'?'Kaufe':'Verkaufe'} ${o.quantity} ${RESOURCES[o.resource].name}</h3><p>${o.side==='buy'?'Höchstens':'Mindestens'} ${money(o.limit,2)} / Stück inkl. Gebühren</p></div><button class="small" ${act('cancelOrder',o.id)}>Löschen</button></div>`).join('')}</div>`:''}`;
}

function amountControl(ui) {
  return `<div class="cash-control"><div class="row"><div><label for="finance-amount">Betrag pro Transaktion</label></div><div class="row gap8"><input id="finance-amount" type="number" min="1" max="100000000000000" inputmode="numeric" value="${ui.amount}" data-setting="amount" class="number" aria-label="Transaktionsbetrag in Euro"><span class="muted">€</span></div></div><div class="cash-buttons">${[-100,-10,-1,1,10,100].map(n=>`<button ${act('amount',n)}>${n>0?'+':'−'}${Math.abs(n)}</button>`).join('')}</div></div>`;
}

function banks(s,ui) {
  return `<div class="grid2">${Object.entries(BANKS).map(([id,b])=>`<section class="panel bank-card"><div class="between"><h3>${b.name} ${info('bank:'+id)}</h3>${icon(b.icon)}</div><div class="bank-value number">${cash(s.banks[id])}</div><div class="rate"><strong>${pct(bankRate(s,id),3)}</strong> Zins pro Spieltag · vor 15 % Steuer</div><p class="fine-print">${b.description}</p><div class="bank-actions"><button ${act('bank',id)} data-side="withdraw"${disabled(s.banks[id]<ui.amount)}>Abheben</button><button class="primary" ${act('bank',id)} data-side="deposit"${disabled(s.cash<ui.amount)}>Einzahlen</button></div></section>`).join('')}<section class="panel bank-card"><div class="between"><h3>Festgeld ${info('fixed')}</h3>${icon('clock')}</div><p class="mt16 muted" style="font-size:11px">Gebunden · ab 500 €</p><label for="fixed-days" class="mt16">Laufzeit wählen</label><select id="fixed-days" class="wfull" data-setting="fixedDays">${[[10,.0014],[20,.0019],[60,.0027]].filter(([days])=>days<=20||s.tier>=2).map(([d,r])=>`<option value="${d}"${ui.fixedDays===d?' selected':''}>${d} Spieltage · ${duration(d*DAY)} echt · ${pct(r,2)} / Tag</option>`).join('')}</select><button class="wfull mt16" ${act('fixed')}${disabled(ui.amount<500||ui.amount>s.cash)}>Festgeld anlegen · ${cash(ui.amount)}</button></section><section class="panel bank-card"><div class="between"><h3>Kontokorrent ${info('credit')}</h3>${icon('bank')}</div><div class="bank-value number">${cash(s.debt)}</div><div class="rate">Schuld · <strong>${pct(debtRate(s),3)}</strong> Zins pro Spieltag</div><div class="rate mt8">Kreditrahmen: <strong>${cash(creditLimit(s))}</strong></div><p class="fine-print">Gemeinsamer Kreditrahmen: ${cash(creditLimit(s))}. Variable Zinsen. Nicht zahlbare Zinsen erhöhen die Schuld. Überziehung senkt täglich die Reputation.</p><div class="bank-actions"><button ${act('repay')}${disabled(ui.amount>s.cash||ui.amount>s.debt)}>Tilgen</button><button ${act('borrow')}${disabled(ui.amount+s.debt+s.loans.reduce((n,l)=>n+l.principal,0)>creditLimit(s))}>Aufnehmen</button></div>${s.tier>=2?`<div class="divider"></div><h3>Investitionskredit ${info('credit')}</h3><p class="fine-print">Fester Zins bei Abschluss: ${pct(debtRate(s)*.8,3)} / Tag. Zehn gleiche Tilgungsraten alle zehn Spieltage. Bei fehlendem Geld wird die Rate ins Kontokorrent umgebucht (−4 Reputation).</p><button class="wfull mt16" ${act('termLoan')}${disabled(s.loans.length>=5||ui.amount+s.debt+s.loans.reduce((n,l)=>n+l.principal,0)>creditLimit(s))}>Investitionskredit aufnehmen</button>`:''}</section></div>${s.loans.length?`<div class="subheading">Laufende Investitionskredite</div><div class="panel">${s.loans.map(l=>`<div class="list-item between"><div><h3>${cash(l.principal)} Restschuld</h3><p>${pct(l.rate,3)} / Tag · nächste Rate ${cash(Math.min(l.principal,l.original/10))} in ${duration(l.nextPayment-s.elapsed)}</p></div><button class="small" ${act('repayLoan',l.id)}${disabled(ui.amount>l.principal||ui.amount>s.cash)}>Sondertilgen</button></div>`).join('')}</div>`:''}<p class="fine-print">Ein Spieltag dauert 24 echte Minuten. Alle Zinssätze beziehen sich auf diese Spieltage. Zinsen und Dividenden unterliegen 15 % Kapitalertragsteuer. Bankkapital ist Teil deines Vermögens.</p>`;
}

function stocks(s,ui) {
  return `<div class="toolbar"><span class="muted" style="font-size:11px">${cash(assets(s).securities)} Depotwert</span>${quantity(ui)}</div>${Object.entries(STOCKS).map(([id,d])=>{
    const p=s.stocks[id],change=p.price/p.previous-1,gain=p.price*p.quantity-p.basis,expanded=ui.open.has(`s-${id}`);
    return `<article class="stock-card"><div class="stock-row"><div><div class="stock-name">${d.name} ${info('stock:'+id)}</div><p>${d.full}</p></div>${chart([...p.history.slice(-47),p.price],false,`${d.name}: Kursverlauf`)}<div class="number">${money(p.price,2)}<small>${change>=0?'+':''}${pct(change,2)} / h</small></div><div class="stock-position"><span class="number">${p.quantity}</span><small>Anteile · ${signed(gain)} Buchgewinn</small></div><div class="market-actions"><button ${act('stock',id)} data-side="sell"${disabled(p.quantity<ui.qty)}>−${ui.qty}</button><button ${act('stock',id)} data-side="buy"${disabled(p.price*ui.qty*1.005>s.cash)}>+${ui.qty}</button></div></div><div class="card-footer"><span>${money(p.report.dps,3)} Dividende / Anteil / Tag</span><button ${act('expand',`s-${id}`)} aria-expanded="${expanded}">Geschäftsbericht ${icon(expanded?'minus':'plus')}</button></div>${expanded?stockAnalysis(s,id):''}</article>`;
  }).join('')}`;
}

function bonds(s,ui) {
  return `<div class="grid3">${Object.entries(BONDS).filter(([id])=>id==='state'||s.tier>=2).map(([id,b])=>`<section class="panel financial-card">${icon(id==='state'?'shield':id==='municipal'?'building':'factory')}<h3>${b.name} ${info('bond:'+id)}</h3><p>${b.days} Spieltage · ${b.risk?pct(b.risk,0)+' Ausfallrisiko':'garantiert'}</p><div class="finance-facts"><div><small>Zins / Spieltag</small><strong class="number">${pct(b.rate,2)}</strong></div><div><small>Echte Laufzeit</small><strong class="number">${duration(b.days*DAY)}</strong></div></div><p>Mindestanlage ${cash(b.min)}. Kapital bis Fälligkeit gebunden.</p><button class="wfull" ${act('bond',id)}${disabled(ui.amount<b.min||ui.amount>s.cash||s.bonds.length>=30)}>Zeichnen · ${cash(ui.amount)}</button></section>`).join('')}</div><p class="fine-print">Risikowerte gelten pro Anleihe bei Fälligkeit. Staatsanleihen sind garantiert. Unternehmensanleihen können einen Teil des eingesetzten Kapitals verlieren. Rückzahlung und Nettozinsen erfolgen automatisch.</p>`;
}

function ventures(s,ui) {
  return `<div class="notice">${icon('info')}<strong>Chancen brauchen Risikokapital.</strong> Jede Beteiligung hat eine feste Erfolgswahrscheinlichkeit. Auch mehrere Fehlschläge hintereinander sind möglich. Lege nur Geld an, das dein Betrieb entbehren kann.</div><div class="grid2">${Object.entries(VENTURES).filter(([,v])=>v.tier<=s.tier).map(([id,v])=>`<section class="panel financial-card"><div class="between"><h3>${v.name} ${info('venture:'+id)}</h3>${icon(v.icon)}</div><p>${pct(v.success,0)} Erfolgswahrscheinlichkeit · ${duration(v.duration)} echt</p><div class="finance-facts"><div><small>Bei Erfolg, vor Steuer</small><strong class="number">${cash(ui.amount*v.multiple)}</strong></div><div><small>Bei Fehlschlag</small><strong class="number">${cash(ui.amount*v.recovery)}</strong></div></div><p>Mindestens ${cash(v.min)} · Kapital bis Abschluss gebunden</p><button ${act('venture',id)}${disabled(ui.amount<v.min||ui.amount>s.cash||s.ventures.length>=12)}>Beteiligen · ${cash(ui.amount)}</button></section>`).join('')}</div>`;
}

function treasuryView(s,ui){
  if(s.tier<2)return '';
  const t=s.treasury;
  return `<section class="panel mt24"><div class="between"><h3>Liquiditätsmanager ${info('treasury')}</h3><button class="small ${t.enabled?'primary':''}" ${act('treasuryToggle')}>${t.enabled?'Aktiv':'Inaktiv'}</button></div><div class="auto-form mt16"><div><label for="treasury-bank">Reservekonto</label><select id="treasury-bank" data-treasury="bank" class="wfull">${Object.entries(BANKS).map(([id,b])=>`<option value="${id}"${t.bank===id?' selected':''}>${b.name}</option>`).join('')}</select></div>${[['floor','Mindestreserve'],['target','Ziel in der Kasse']].map(([field,name])=>`<div><label for="treasury-${field}">${name}</label><div class="input-stepper"><button ${act('treasuryStep',field)} data-delta="-${ui.amount}" aria-label="${name} um ${ui.amount} senken">−</button><input type="number" inputmode="numeric" id="treasury-${field}" value="${t[field]}" min="50" max="1000000000000" data-treasury="${field}"><button ${act('treasuryStep',field)} data-delta="${ui.amount}" aria-label="${name} um ${ui.amount} erhöhen">+</button></div></div>`).join('')}</div></section>`;
}

function savingsPlansView(s,ui){
  if(s.tier<2)return '';
  return `<section class="panel mt24"><div class="between"><h3>Regelmäßig investieren ${info('plan')}</h3>${icon('refresh')}</div><div class="auto-form mt16"><div><label for="plan-stock">Wert</label><select id="plan-stock" data-setting="planStock">${Object.entries(STOCKS).map(([id,d])=>`<option value="${id}"${ui.planStock===id?' selected':''}>${d.name}</option>`).join('')}</select></div><div><label for="plan-budget">Rate (€)</label><input id="plan-budget" type="number" inputmode="numeric" min="10" max="1000000000000" value="${ui.amount}" data-setting="amount"></div><div><label for="plan-period">Abstand</label><select id="plan-period" data-setting="planPeriod">${[1,5,10].map(n=>`<option value="${n}"${ui.planPeriod===n?' selected':''}>${n} Spieltag${n===1?'':'e'}</option>`).join('')}</select></div></div><button class="mt16" ${act('createPlan')}${disabled(ui.amount<10||s.savingsPlans.some(p=>p.stock===ui.planStock))}>Sparplan einrichten</button>${s.savingsPlans.length?`<div class="divider"></div>${s.savingsPlans.map(p=>`<div class="list-item between"><div><h3 style="font-size:12px">${STOCKS[p.stock].name} · ${cash(p.budget)} / ${p.period} Spieltag${p.period===1?'':'e'}</h3><p>Nächste Rate in ${duration(p.next-s.elapsed)} · ${p.executions} ausgeführt · ${p.skipped} übersprungen</p></div><button class="small" ${act('cancelPlan',p.id)}>Beenden</button></div>`).join('')}`:''}</section>`;
}

function stockAnalysis(s,id){
  const p=s.stocks[id],r=p.report,next=(Math.floor(s.elapsed/(5*DAY))+1)*5*DAY;
  const multiple=p.price/r.fair;
  return `<div class="card-detail"><div class="between"><span class="eyebrow">Geschäftsbericht · Tag ${Math.floor(r.at/DAY)+1}</span>${info('stock:'+id)}</div><div class="detail-grid mt16"><p>Umsatz je Anteil / Spieljahr<strong class="number">${money(r.revenue,2)}</strong></p><p>Gewinn je Anteil / Spieljahr<strong class="number">${money(r.eps,2)}</strong></p><p>Gewinnmarge<strong class="number">${pct(r.margin,1)}</strong></p><p>Kurs-Gewinn-Verhältnis<strong class="number">${number(p.price/r.eps,1)}</strong></p><p>Modell-Ertragswert<strong class="number">${money(r.fair,2)}</strong></p><p>Kurs / Ertragswert<strong class="number">${number(multiple,2)}×</strong></p><p>Absatzpreisindex<strong class="number">${number(r.outputIndex*100,1)}</strong></p><p>Zulieferpreisindex<strong class="number">${number(r.inputIndex*100,1)}</strong></p><p>Umsatz zum Vorbericht<strong class="number">${r.growth>=0?'+':''}${pct(r.growth,1)}</strong></p><p>Dividende je Anteil / Tag<strong class="number">${money(r.dps,3)}</strong></p></div><div class="between muted" style="font-size:10px"><span>Nächster Bericht in ${duration(next-s.elapsed)}</span><span>${multiple<.9?'Unter Modellwert':multiple>1.1?'Über Modellwert':'Nahe am Modellwert'}</span></div>${s.tier>=2?`<div class="divider"></div><div class="between"><div><h3 style="font-size:12px">Dividenden ${info('stock:'+id)}</h3><p style="font-size:10px">${cash(p.reserve)} Wiederanlage-Reserve</p></div><button class="small ${p.drip?'primary':''}" ${act('drip',id)}>${p.drip?'Wiederanlage aktiv':'Wiederanlage starten'}</button></div>`:''}</div>`;
}

function propertyView(s,ui){
  return `<div class="toolbar"><span class="muted" style="font-size:11px">${cash(assets(s).properties)} Marktwert · ${cash(s.stats.rent)} Mieten netto erhalten</span>${quantity(ui)}</div><div class="grid2">${Object.entries(PROPERTIES).filter(([,d])=>d.tier<=s.tier).map(([id,d])=>{const p=s.properties[id],unit=d.cost*p.index,net=(d.rent*p.occupancy-d.maintenance)*.85;return `<section class="panel"><div class="between"><div class="row gap8">${icon(d.icon)}<h3>${d.name} ${info('property:'+id)}</h3></div><span class="number" style="font-size:25px">${p.count}</span></div><div class="finance-facts mt24"><div><small>Preis je Einheit</small><strong class="number">${cash(unit)}</strong></div><div><small>Vermietung</small><strong class="number">${pct(p.occupancy,1)}</strong></div><div><small>Netto / Tag je Einheit</small><strong class="number">${cash(net)}</strong></div></div><div class="mt16">${chart(p.history.map(v=>v*d.cost),false,'Immobilienbewertung')}</div><div class="bank-actions mt16"><button ${act('property',id)} data-side="sell"${disabled(p.count<ui.qty)}>−${ui.qty} verkaufen</button><button ${act('property',id)} data-side="buy"${disabled(unit*ui.qty*1.02>s.cash)}>+${ui.qty} kaufen</button></div><div class="mt8 muted" style="font-size:10px">Kauf gesamt inkl. Kosten: ${cash(unit*ui.qty*1.02)}</div></section>`;}).join('')}</div>`;
}

function hedgesView(s,ui){
  const id=RESOURCES[ui.optionResource]?.tier<=s.tier?ui.optionResource:'wood',q=optionQuote(s,id,ui.optionType,ui.qty,ui.optionDays);
  return `<div class="toolbar"><div class="row"><span class="muted" style="font-size:11px">Preisschwankungen begrenzen ${info('options')}</span></div>${quantity(ui)}</div><section class="panel"><div class="auto-form"><div><label for="option-resource">Referenzware</label><select id="option-resource" data-setting="optionResource">${Object.entries(RESOURCES).filter(([,d])=>d.tier<=s.tier).map(([r,d])=>`<option value="${r}"${r===id?' selected':''}>${d.name}</option>`).join('')}</select></div><div><label for="option-type">Schutz</label><select id="option-type" data-setting="optionType"><option value="put"${ui.optionType==='put'?' selected':''}>Put · gegen fallende Preise</option><option value="call"${ui.optionType==='call'?' selected':''}>Call · gegen steigende Preise</option></select></div><div><label for="option-days">Laufzeit</label><select id="option-days" data-setting="optionDays">${[1,3,7].map(d=>`<option value="${d}"${ui.optionDays===d?' selected':''}>${d} Spieltag${d===1?'':'e'} · ${duration(d*DAY)} echt</option>`).join('')}</select></div></div><div class="finance-facts mt24"><div><small>Vereinbarter Preis ${info('optionModel')}</small><strong class="number">${money(q.strike,2)}</strong></div><div><small>Menge</small><strong class="number">${ui.qty}</strong></div><div><small>Prämie = maximaler Verlust</small><strong class="number">${money(q.premium,2)}</strong></div></div><button class="mt24" ${act('buyOption')}${disabled(q.premium>s.cash||s.options.length>=20)}>Absicherung kaufen · ${money(q.premium,2)}</button></section>${s.options.length?`<div class="subheading">Laufende Absicherungen</div><div class="grid2">${s.options.map(o=>{const value=optionPrice(referencePrice(s,o.resource),o.strike,Math.max(0,(o.end-s.elapsed)/DAY),o.volatility,o.type)*o.quantity;return `<section class="panel"><div class="between"><h3>${o.type==='put'?'Put':'Call'} · ${RESOURCES[o.resource].name} ${info('options')}</h3><span class="number">${o.quantity}</span></div><div class="detail-grid mt16"><p>Basispreis<strong>${money(o.strike,2)}</strong></p><p>Referenzkurs jetzt<strong>${money(referencePrice(s,o.resource),2)}</strong></p><p>Modellwert vor Verkaufskosten<strong>${money(value,2)}</strong></p><p>Restlaufzeit echt<strong>${duration(o.end-s.elapsed)}</strong></p></div><button class="small" ${act('sellOption',o.id)}>Vorzeitig verkaufen</button></section>`;}).join('')}</div>`:''}`;
}

function plannerView(s){
  const rows=supplyPlan(s);
  return `<div class="between mt8"><h3>Deine Kette, in Zahlen. ${info('planner')}</h3><span class="eyebrow">Sollmengen / h</span></div><div class="plan-table mt24"><div class="plan-row plan-heading"><span>Ware</span><span>Produktion</span><span>Verbrauch</span><span>Saldo</span><span>Reichweite</span><span></span></div>${rows.map(r=>`<div class="plan-row"><span class="row gap8">${icon(RESOURCES[r.id].icon)}${RESOURCES[r.id].name} ${info('resource:'+r.id)}</span><span class="number" data-label="Produktion">${number(r.output,1)}</span><span class="number" data-label="Verbrauch">${number(r.input,1)}</span><span class="number ${r.net<0?'negative':''}" data-label="Saldo">${signed(r.net,'')}</span><span class="number" data-label="Reichweite">${Number.isFinite(r.hours)?number(r.hours,1)+' h':'∞'}</span><button class="small" ${act('goResource',r.id)}>Markt</button></div>`).join('')}</div>`;
}

export function finance(s,ui) {
  const tabs=[['bank','Bank'],['stocks','Börse'],['bonds','Anleihen'],['ventures','Beteiligungen'],...(s.tier>=2?[['properties','Sachwerte']]:[]),...(s.tier>=3?[['hedges','Absicherung']]:[])];
  const holdings=s.bonds.length||s.ventures.length?`<div class="subheading">Gebundenes Kapital</div><div class="panel">${s.bonds.map(b=>`<div class="list-item between"><div><h3 style="font-size:13px">${b.type==='fixed'?'Festgeld':BONDS[b.type].name} · ${cash(b.principal)}</h3><p>Fällig in ${duration(b.end-s.elapsed)} · ${pct(b.rate,2)} / Spieltag</p></div>${b.type==='fixed'?`<button class="small" ${act('redeemFixed',b.id)}>Auflösen</button>`:icon('clock')}</div>`).join('')}${s.ventures.map(v=>`<div class="list-item between"><div><h3 style="font-size:13px">${VENTURES[v.type].name} · ${cash(v.principal)}</h3><p>Ergebnis in ${duration(v.end-s.elapsed)}</p></div>${icon('compass')}</div>`).join('')}</div>`:'';
  return `${head('Zeit ist Kapital','Geld in Bewegung.','Lege Rücklagen an. Finanziere Wachstum. Trage bewusst Risiken.')}<div class="toolbar"><div class="segmented finance-tabs" style="--tab-columns:${tabs.length===4?2:3}">${tabs.map(([id,n])=>`<button ${act('financeTab',id)} class="${ui.financeTab===id?'active':''}">${n}</button>`).join('')}</div><span class="muted" style="font-size:11px">${cash(s.cash)} verfügbar</span></div>${!['stocks','properties','hedges'].includes(ui.financeTab)?amountControl(ui):''}${ui.financeTab==='bank'?banks(s,ui)+treasuryView(s,ui):ui.financeTab==='stocks'?stocks(s,ui)+savingsPlansView(s,ui):ui.financeTab==='bonds'?bonds(s,ui):ui.financeTab==='properties'?propertyView(s,ui):ui.financeTab==='hedges'?hedgesView(s,ui):ventures(s,ui)}${holdings}`;
}

export function researchView(s,ui) {
  return `${head('Wissen verändert alles','Besser statt größer.','Forschungsinstitute erzeugen Punkte. Verbesserungen wirken dauerhaft.',`<div class="align-right"><div class="eyebrow">Forschung</div><div class="number" style="font-size:28px">${number(s.points,1)} <small>FP</small></div></div>`)}${!s.infra.lab?`<div class="notice"><strong>Ein Ort für neue Ideen.</strong> Baue dein erstes Forschungsinstitut unter Betriebe → Infrastruktur. Es erzeugt einen Forschungspunkt pro Spielstunde und kostet 10 €/h.<div class="mt16"><button class="small" ${act('goLab')}>Zur Infrastruktur ${icon('arrow')}</button></div></div>`:''}<div class="grid3">${Object.entries(RESEARCH).filter(([,r])=>r.tier<=s.tier).map(([id,r])=>{const level=s.research[id],cost=researchCost(s,id),max=level>=r.max;return `<section class="panel research-card"><div class="between">${icon(r.icon)}<span class="eyebrow">Stufe ${level}</span></div><h3>${r.name} ${info('research:'+id)}</h3><div class="level-dots">${Array.from({length:r.max},(_,i)=>`<i class="${i<level?'filled':''}"></i>`).join('')}</div><div class="research-cost"><span class="muted">${max?'Abgeschlossen':`${cost.points} FP · ${cash(cost.cash)}`}</span><button class="small ${!max&&s.points>=cost.points&&s.cash>=cost.cash?'primary':''}" ${act('research',id)}${disabled(max||s.points<cost.points||s.cash<cost.cash)}>${max?icon('check'):'Forschen'}</button></div></section>`;}).join('')}</div>`;
}

export function contracts(s) {
  const card=(c,active)=>`<article class="contract-card"><div class="between"><div class="row gap8">${icon(RESOURCES[c.resource].icon)}<h3>${RESOURCES[c.resource].name} ${info('contracts')}</h3></div><span class="eyebrow">${active?'Laufend':`+${number((c.premium-1)*100)} % Prämie`}</span></div><div class="contract-quantity number">${c.quantity} <small>Einheiten</small></div><div class="contract-reward number">${cash(c.reward)}</div><p class="mt8">${active?`Noch ${duration(c.end-s.elapsed)} echte Zeit`:`Lieferfrist: ${duration(c.duration)} echte Zeit`}</p>${active?`${meter('Bereit zur Lieferung',s.inventory[c.resource],c.quantity)}<div class="row"><button class="wfull primary" ${act('fulfill',c.id)}${disabled(s.inventory[c.resource]+1e-7<c.quantity)}>Liefern</button><button class="icon-button" ${act('abandon',c.id)} aria-label="Vertrag aufgeben">${icon('close')}</button></div>`:`<button class="wfull mt24" ${act('accept',c.id)}${disabled(s.contracts.length>=3)}>Auftrag annehmen</button>`}</article>`;
  return `${head('Vertrauen wird belohnt','Versprechen mit Wert.','Liefere Waren zum vereinbarten Preis. Erhalte Prämien, Reputation und Forschungspunkte.')}<div class="subheading" style="margin-top:0">Laufende Verträge <span class="muted">${s.contracts.length} / 3</span></div>${s.contracts.length?`<div class="grid3">${s.contracts.map(c=>card(c,true)).join('')}</div>`:`<div class="panel flat">${empty('Noch kein Versprechen.','Nimm einen Auftrag an, den deine Produktionskette rechtzeitig erfüllen kann.','file')}</div>`}<div class="subheading">Neue Gelegenheiten <span class="muted" style="font-size:10px">Neue Angebote alle 6 echten Minuten</span></div><div class="grid3">${s.board.map(c=>card(c,false)).join('')}</div><p class="fine-print">Du lieferst die gesamte Menge per Schaltfläche. Achte auf automatische Verkäufe: Halte für Aufträge genug Ware zurück. Erfüllung: +2 Reputation und Forschungspunkte. Fristablauf oder Aufgabe: −3 Reputation, keine Geldstrafe. Bei Prämien ist der Marktpreis zum Zeitpunkt des Angebots maßgeblich.</p>`;
}

export function journal(s) {
  return `${head('Deine Geschichte','Entscheidungen hinterlassen Spuren.','Ereignisse, Entdeckungen und die letzten 100 Einträge deines Unternehmens.')}<div class="timeline">${s.journal.map(j=>`<div class="timeline-item ${esc(j.type)}"><small>TAG ${Math.floor(j.at/DAY)+1} · ${String(Math.floor(j.at%DAY/HOUR)).padStart(2,'0')}:00</small><p class="mt8">${esc(j.text)}</p></div>`).join('')}</div>`;
}

export function statistics(s) {
  const a=assets(s), earned=s.achievements.length;
  return `${head('Was bleibt','Eine Bilanz deiner Entscheidungen.')}<div class="grid2"><section class="panel"><div class="panel-header"><h3>Vermögensbilanz</h3>${icon('file')}</div>${[['Liquidität',a.cash],['Warenlager',a.inventory],['Anlagevermögen (Buchwert)',a.buildings],...(s.tier>=1?[['Bankguthaben',a.banks],['Wertpapiere inkl. Depotreserve',a.securities],['Anleihen & Festgeld',a.bonds],['Beteiligungen (Einstand)',a.ventures],['Verbindlichkeiten',-a.debt]]:[]),...(s.tier>=2?[['Anlageimmobilien',a.properties]]:[]),...(s.tier>=3?[['Absicherungen (Modellwert)',a.options]]:[]),['Nettovermögen',a.total]].map(([name,n])=>`<div class="balance-line"><span>${name}</span><span class="number">${cash(n)}</span></div>`).join('')}</section><section class="panel"><div class="panel-header"><h3>Seit der Gründung</h3>${icon('chart')}</div>${[['Gesamter Warenumsatz',s.stats.revenue],['Laufende Ausgaben',s.stats.expenses],...(s.tier>=1?[['Nettozinsen',s.stats.interest],['Nettodividenden',s.stats.dividends]]:[]),...(s.tier>=2?[['Nettomieten',s.stats.rent]]:[]),...(s.tier>=3?[['Absicherungen: realisiertes Ergebnis',s.stats.optionPnl]]:[]),['Gezahlte / gestundete Steuern',s.stats.taxes],['Höchstes Nettovermögen',s.stats.peak]].map(([name,n])=>`<div class="balance-line"><span>${name}</span><span class="number">${cash(n)}</span></div>`).join('')}<div class="balance-line"><span>Erfüllte Verträge</span><span class="number">${s.stats.contracts}</span></div><div class="balance-line"><span>Simulierte echte Zeit</span><span class="number">${duration(s.elapsed)}</span></div></section></div><div class="subheading">Meilensteine <span class="muted">${earned} entdeckt</span></div><div class="grid3">${ACHIEVEMENTS.filter(a=>s.achievements.includes(a.id)||['firstBuild','firstTrade','ten','contract'].includes(a.id)||(s.tier>=1&&['chain','research','invest'].includes(a.id))||(s.tier>=2&&a.id==='diverse')).map(a=>`<div class="achievement ${s.achievements.includes(a.id)?'done':''}">${icon(s.achievements.includes(a.id)?'trophy':'compass')}<div><h3>${a.name}</h3><p>${a.description}</p><small>${s.achievements.includes(a.id)?'Erreicht':`Prämie ${cash(a.reward)}`}</small></div></div>`).join('')}</div>${s.stats.peak>=10000000?`<section class="panel mt24"><div class="between"><h3>Das Vermächtnis</h3>${icon('orbit')}</div><p class="mt16" style="font-size:12px">Ab 100 Millionen € Höchstvermögen kannst du eine neue Holding gründen. Dein Unternehmen startet neu; Vermächtnispunkte geben dauerhaft +8 % Produktion und +4 % Forschung pro Punkt. Je größer dein bisheriger Höchstwert, desto größer das Vermächtnis.</p><p class="fine-print">Aktuell: ${s.legacy} Punkte · nächste Gründung: +${prestigeReward(s)} Punkte. Produktionsanlagen, Geld, Forschung und Finanzanlagen werden zurückgesetzt. Exportiere zuvor deinen Spielstand.</p><button class="mt24" ${act('prestige')}${disabled(!prestigeReward(s))}>Neue Holding gründen</button></section>`:''}`;
}

export function more(s) {
  const links=[...(s.tier>=1?[['research','flask','Forschung','Ideen werden zu Vorsprung']]:[]),['contracts','file','Lieferaufträge','Zuverlässigkeit zahlt sich aus'],['statistics','chart','Bilanz & Meilensteine','Was du aufgebaut hast'],['journal','clock','Chronik','Deine Unternehmensgeschichte'],['saves','save','Spielstände','Speichern, laden, exportieren'],['guide','book','Spielanleitung','Verstehe dein System'],['install','download','iPhone-Installation','Dein Spiel auf dem Home-Bildschirm'],['menu','menu','Hauptmenü','Ein Moment zum Durchatmen']];
  return `${head('Dein Unternehmen','Es gibt mehr zu entdecken.')}<div class="more-grid">${links.map(([id,glyph,name,sub])=>`<button class="more-link" ${act(['saves','guide','install','menu'].includes(id)?id:'tab',id)}>${icon(glyph)}<span><strong>${name}</strong><small>${sub}</small></span></button>`).join('')}</div><section class="panel flat mt24"><div class="between"><div><h3>${esc(s.name)}</h3><p class="fine-print">Dein Name für diese Wirtschaft.</p></div><button class="small" ${act('rename')}>Umbenennen</button></div></section>`;
}

export function savesView(s,ui,saves) {
  return `${head('Ein sicherer Stand','Deine Geschichte gehört dir.','Drei manuelle Spielstände, automatische Sicherung und Dateiexport.')}<div class="grid2">${saves.map(slot=>`<section class="save-slot"><div class="between"><h3>${slot.slot==='auto'?'Automatischer Spielstand':`Spielstand ${slot.slot.slice(-1)}`}</h3>${icon('save')}</div>${slot.error?`<p>Beschädigt: ${esc(slot.error)}</p>`:slot.empty?'<p>Noch kein Spielstand.</p>':`<p>${esc(slot.name)} · ${TIERS[slot.tier].name}<br>${cash(slot.cash)} · Tag ${Math.floor(slot.elapsed/DAY)+1}<br>${new Date(slot.saved).toLocaleString('de-DE')}${slot.recovered?' · Sicherungskopie':''}</p>`}<div class="row">${slot.slot!=='auto'?`<button ${act('saveSlot',slot.slot)}${disabled(!s)}>Speichern</button>`:''}<button ${act('loadSlot',slot.slot)}${disabled(slot.empty||slot.error)}>Laden</button>${slot.slot!=='auto'&&!slot.empty?`<button ${act('deleteSlot',slot.slot)} aria-label="Spielstand löschen" class="icon-button">${icon('close')}</button>`:''}</div></section>`).join('')}</div><section class="panel mt24"><div class="between wrap"><div><h3>Eine Kopie für alle Fälle.</h3><p class="fine-print">Browserdaten können gelöscht werden. Ein Export bleibt deine unabhängige Sicherung.</p></div><div class="row wrap"><button ${act('export')}${disabled(!s)}>${icon('download')} Exportieren</button><button ${act('import')}>${icon('upload')} Importieren</button></div></div></section>${ui.saveError?`<div class="notice mt24"><strong>Lokaler Speicher eingeschränkt.</strong> ${esc(ui.saveError)} Exportiere deinen Spielstand, bevor du die App schließt.</div>`:''}<p class="fine-print">Automatisch alle 15 Sekunden, nach Aktionen und beim Verlassen. Jeder Speicherplatz hält zusätzlich seine letzte gültige Sicherungskopie vor. Manuelle Spielstände sind Momentaufnahmen; beim Laden wird die seit ihrer Sicherung verstrichene Zeit simuliert. Safari und die Home-Bildschirm-App können getrennte Speicher verwenden: Übertrage deinen Spielstand bei Bedarf per Export und Import.</p>`;
}

export function guide(s) {
  const tier=s?.tier||0;
  const section=(title,body,open=false)=>`<details${open?' open':''}><summary>${title}</summary>${body}</details>`;
  return `${head('Ein System, das du verstehen kannst','Wenige Knöpfe. Viele Möglichkeiten.')}<div class="guide">${section('01 — Die ersten fünf Minuten',`<ol><li>Starte mit einem <strong>Holzfäller</strong> unter Betriebe. Du hast 1.200 € und eine kleine Materialreserve.</li><li>Öffne den <strong>Markt</strong>. Verkaufe Holz von Hand oder öffne „Automatik“ bei Holz.</li><li>Wähle <strong>Überschüsse verkaufen</strong> und setze „Verkaufen über“ auf etwa 20. Dein Holzfäller verdient nun laufend Geld.</li><li>Erweitere vorsichtig. Prüfe Personal und Transport in der Übersicht. Infrastruktur schafft Platz zum Wachsen.</li><li>Lieferaufträge bringen Prämien. Bei <strong>2.000 € Nettovermögen</strong> eröffnet sich ein neuer Horizont.</li></ol><p>Neue Inhalte bleiben verborgen, bis du sie entdeckst. Es gibt keinen Zeitdruck und keine endgültige Insolvenz. Du entscheidest selbst, wie schnell dein Unternehmen wächst.</p>`,true)}${section('02 — Zeit, Offline-Fortschritt und Speichern',`<p><strong>1 echte Minute = 1 Spielstunde. 24 echte Minuten = 1 Spieltag.</strong> Die Produktion wird jede echte Sekunde berechnet. Bei der Rückkehr simuliert NULL die verstrichene Zeit mit denselben Produktionsketten, Preisen, Engpässen und Zinsen.</p><p>Pro Abwesenheit werden bis zu <strong>sieben echte Tage</strong> nachgerechnet. Mehrzeit wird im Rückkehrbericht ausgewiesen. Fehlende Rohstoffe, leere Kassen oder volle Lager begrenzen die Produktion auch offline. Ereignisse und fällige Anlagen werden ebenfalls berechnet.</p><p>Es wird alle 15 Sekunden und nach Entscheidungen automatisch gespeichert. Nutze zusätzlich manuelle Speicherplätze und exportiere gelegentlich eine Datei. Vor einer langen Abwesenheit: Verkäufe automatisieren, Vorprodukte reservieren und Betriebskapital vorhalten.</p>`)}${section('03 — Produktion, Kosten und Engpässe',`<p>Ein Betrieb produziert die angegebene Menge <strong>pro Spielstunde je aktiver Einheit</strong>. Verarbeitende Betriebe benötigen ihre Vorprodukte im Lager. In den Details kannst du Betriebe pausieren, wieder aktivieren oder ausbauen.</p><p><strong>Personal, Energie und Transport</strong> sind gemeinsame Kapazitäten. Der stärkste Engpass begrenzt alle Betriebe. Bei fehlenden Vorprodukten oder vollem Ausgangslager wird der einzelne Betrieb gedrosselt. Löhne fallen nur für die tatsächlich laufende Produktion an.</p><p>Wohnquartiere schaffen Personal, Lagerhallen vergrößern die Kapazität <strong>je Ressource</strong>. Rückbau erstattet 45 % des Buchwerts. Neue Betriebe desselben Typs werden mit jedem Bau um 13 % teurer. Fehlende Baumaterialien werden beim Bau automatisch zum Marktpreis beschafft und sind im angezeigten Preis enthalten.</p><p>Mit den Schrittweiten <strong>1, 10 und 100</strong> steuerst du Bauen, Rückbauen, Handel und Betriebseinstellungen. Ausbaustufen gelten für alle Betriebe eines Typs.</p>`)}${section('04 — Markt und Automatik',`<p>Mittelkurs, Kaufpreis und Verkaufspreis unterscheiden sich: <strong>Gebühren und der eigene Preiseffekt</strong> werden in den Handel eingerechnet. Große Käufe verteuern, große Verkäufe verbilligen eine Ware. Knappheit normalisiert sich langsam durch den simulierten Außenmarkt. Konjunktur und Ereignisse verändern die Nachfrage.</p><p><strong>Überschüsse verkaufen:</strong> verkauft alles über deiner Verkaufsschwelle.<br><strong>Vorräte auffüllen:</strong> kauft bis zur Einkaufsschwelle.<br><strong>Einkauf & Verkauf:</strong> kombiniert beides. Die Einkaufsschwelle darf die Verkaufsschwelle nicht übersteigen.</p><p>Halte bei Vorprodukten Reserven für nachgelagerte Betriebe und Lieferaufträge. Automatische Einkäufe lassen eine kleine Lohnreserve frei. Automatik folgt auch bei geschlossener App deinen Regeln.</p>${tier>=1?'<p><strong>Limitaufträge</strong> werden als vollständige Menge ausgeführt, wenn der Durchschnittspreis einschließlich Gebühren dein Limit erreicht und genügend Geld beziehungsweise Ware vorhanden ist. Sie reservieren kein Kapital und bleiben sonst bestehen.</p>':''}`)}${section('05 — Wenn es nicht weitergeht',`<p><strong>Kein Geld:</strong> Verkaufe Waren, löse Bankguthaben auf${tier>=1?', verkaufe Wertpapiere oder nutze einen besicherten Kredit':''}. „Lager zu Geld machen“ erscheint bei sehr knapper Liquidität. Du kannst Betriebe für 45 % ihres Buchwerts zurückbauen. Lohnmangel pausiert die Produktion, statt unbemerkt neue Betriebsschulden zu erzeugen.</p><p><strong>Keine Produktion:</strong> Prüfe aktive Einheiten, Vorprodukte, freien Lagerplatz und die Kapazitäten in der Übersicht. Neue Wohnquartiere lösen Personalmangel. Verkaufe Überschüsse, um Lager zu leeren.</p><p><strong>Keine neue Epoche:</strong> Entdeckungen richten sich nach deinem bisher höchsten Nettovermögen, einschließlich Anlagen, Bankguthaben und Waren abzüglich Schulden. Bereits entdeckte Inhalte bleiben freigeschaltet.</p>`)}${tier>=1?section('06 — Banken, Börse und Risiko',`<p>Reservekonto und Tagesgeld bleiben verfügbar. Tagesgeldzinsen folgen der Konjunktur. <strong>Festgeld</strong> zahlt höhere feste Zinsen, bindet aber Kapital. Vorzeitige Auflösung kostet 2 % des Einstands und alle aufgelaufenen Zinsen.</p><p><strong>Kontokorrent</strong> ist ein variabler, durch Vermögen und Reputation begrenzter Kredit. Zinsen werden laufend gezahlt; fehlen Mittel, wachsen die Schulden. Investitionskredite werden nach Freischaltung in festen Raten getilgt.</p><p>Aktien reagieren auf die zugehörigen Branchen und auf Zufall. Dividenden werden täglich ausgeschüttet. <strong>Anleihen</strong> haben feste Laufzeiten und gegebenenfalls ein Ausfallrisiko. <strong>Beteiligungen</strong> zahlen bei Erfolg ein Vielfaches, bei Misserfolg nur einen Restbetrag oder nichts. Wahrscheinlichkeiten gelten unabhängig pro Anlage und garantieren kein Ergebnis.</p><p>15 % Kapitalertragsteuer auf Zinsen, Dividenden und realisierte Gewinne. Zusätzlich fallen täglich <strong>12 % auf positiven operativen Überschuss</strong> aus Warenumsatz minus Wareneinkauf und Betriebskosten an. Nicht bezahlbare Unternehmenssteuer wird zur Kontokorrentschuld.</p>`):''}${tier>=1?section('07 — Forschung und Wachstum',`<p>Forschungsinstitute erzeugen einen Punkt pro Spielstunde und kosten 10 €/h. Neue Forschungsstufen benötigen Punkte und Geld. Verbesserungen gelten für das gesamte Unternehmen. Forschungskosten steigen mit jeder Stufe.</p><p>Bei Wachstum ändern sich deine Probleme. Eine neue Kette braucht Zulieferer, genügend Energie, Personal, Transport und Betriebskapital. Neue Freischaltungen verraten sich erst beim Erreichen des nächsten Durchbruchs.</p>`):''}${section('Auf dem iPhone offline spielen',`<ol><li>Öffne die GitHub-Pages-Adresse in <strong>Safari</strong>.</li><li>Warte auf <strong>„Offline bereit“</strong>. Die komplette App wird lokal zwischengespeichert.</li><li>Tippe auf <strong>Teilen → Zum Home-Bildschirm</strong> und bestätige.</li><li>Öffne NULL über das neue Symbol. Starte dort dein Unternehmen oder importiere einen vorhandenen Spielstand.</li><li>Teste einmal im Flugmodus. Danach kannst du überall spielen.</li></ol><p>Die Installation speichert die App; deine Spielstände liegen separat im lokalen Browser-Speicher. Exportiere wichtige Spielstände als Datei. Updates werden angeboten, sobald du wieder online bist.</p>`)}<p class="fine-print mt24">NULL simuliert ein in sich geschlossenes Spielsystem. Preise und Finanzprodukte beziehen sich ausschließlich auf diese Spielwelt.</p></div>`;
}
